#include <future>
#include <iostream>
#include <stdexcept>
namespace b=biglybtc::core;namespace i=b::tags::internal;namespace r=b::tags::runtime;
namespace {
void need(bool value,const char* message){if(!value){throw std::runtime_error(message);}}
r::Text text(std::string_view value){return {value.begin(),value.end()};}
bool same(const i::Snapshot& a,const i::Snapshot& b){if(a.revision!=b.revision||a.entries.size()!=b.entries.size()){return false;}for(std::size_t at=0;at<a.entries.size();++at){if(a.entries[at].id!=b.entries[at].id||a.entries[at].rawName!=b.entries[at].rawName){return false;}}return true;}
void actualInternalConstructorsAndRoster(){std::ifstream file(INTERNAL_TAG_ROSTER_FIXTURE,std::ios::binary);auto source=b::Document::parse(std::string{std::istreambuf_iterator<char>(file),{}});need(bool(source),"Actual internal type source fixture");auto owner=i::Owner::create();need(bool(owner),"Internal metadata owner");std::vector<i::Token> allocated;unsigned rows=0;
 for(const auto& row:source->find("rows")->children){auto action=row.find("action")->bytes;
  if(action=="detached"||action=="registered-second"||action=="duplicate-name"||action=="next-id"){
   const r::Text name=action=="detached"?u"Generated first":action=="next-id"?u"Generated final":u"Generated second";auto token=(*owner)->createTag(name,action!="detached");need(bool(token),"Actual source allocation refused");allocated.push_back(*token);
  }else if(action=="attach-first"){need(bool((*owner)->attach(allocated[0])),"Actual detached registration");}
  else if(action=="rename-first"){need(bool((*owner)->rename(allocated[0],u"Generated renamed")),"Actual rename");}
  else if(action=="remove-second"){need(bool((*owner)->remove(allocated[1])),"Actual removal");}
  auto snapshot=(*owner)->snapshot();need(bool(snapshot),"Current owning roster snapshot");need(snapshot->type==row.find("type")->integer&&snapshot->persistent==bool(row.find("persistent")->integer)&&snapshot->automatic==bool(row.find("auto")->integer)&&snapshot->properties==bool(row.find("properties")->integer),"Original internal type metadata differs");const auto& tags=row.find("tags")->children;need(snapshot->entries.size()==tags.size(),"Detached/removed tags entered registered roster");for(std::size_t at=0;at<tags.size();++at){const auto& entry=snapshot->entries[at];const auto& actual=tags[at];need(entry.id==actual.find("id")->integer&&entry.rawName==text(actual.find("raw_name")->bytes)&&snapshot->taggableType==actual.find("kind")->integer,"Original registered order/name/identity differs");r::Reference ref{0,0,5,entry.id};need(ref.uid()==actual.find("uid")->integer,"Original internal UID differs");}const auto& ids=row.find("allocated")->children;need(ids.size()==allocated.size(),"Original ID allocation sequence differs");for(std::size_t at=0;at<ids.size();++at){need(allocated[at].id()==ids[at].integer,"Removed IDs reused or detached allocation omitted");}++rows;
 }need(rows==8,"Actual internal source states lost");
}
void lifetimeIsolationAndOwningNames(){auto owner=i::Owner::create(),foreign=i::Owner::create();need(owner&&foreign,"Isolated internal owners");r::Text input=u"Generated immutable";auto token=(*owner)->createTag(input,true);need(bool(token),"Generated registered token");auto first=(*owner)->snapshot();need(bool(first),"Held raw metadata");input.assign(u"Changed input");need(first->entries[0].rawName==u"Generated immutable","Owner borrowed caller name");need(!(*foreign)->rename(*token,u"Foreign")&&!(*foreign)->attach(*token),"Foreign owner accepted matching numeric ID");auto cross=std::async(std::launch::async,[&]{auto snapshot=(*owner)->snapshot();auto renamed=(*owner)->rename(*token,u"Foreign thread");auto closed=(*owner)->close();return !snapshot&&snapshot.error()==i::Error::WrongThread&&!renamed&&renamed.error()==i::Error::WrongThread&&!closed&&closed.error()==i::Error::WrongThread;});need(cross.get(),"Foreign thread entered metadata owner");need(bool((*owner)->rename(*token,u"Generated next")),"Current token rename");need(first->entries[0].rawName==u"Generated immutable","Held snapshot changed with owner");need(bool((*owner)->remove(*token))&&!(*owner)->attach(*token)&&!(*owner)->rename(*token,u"Removed"),"Removed token regained authority");auto after=(*owner)->snapshot();need(after&&after->entries.empty(),"Removed tag remains registered");need(bool((*owner)->close())&&bool((*owner)->close())&&!(*owner)->snapshot()&&!(*owner)->createTag(u"Closed",true),"Closed owner reopened");owner->reset();need(!(*foreign)->remove(*token),"Expired token entered a new owner");need(token->id()==1,"Pure allocated ID lost after close");
}
void quotasAndCollectedDetachedTokens(){i::Limits limit;limit.objects=2;limit.registered=1;limit.nameUnits=4;limit.totalUnits=6;limit.creations=3;auto owner=i::Owner::create(limit);need(bool(owner),"Bounded internal owner");auto one=(*owner)->createTag(u"one",false),two=(*owner)->createTag(u"two",false);need(one&&two,"Bounded detached allocations");auto before=(*owner)->snapshot();need(before&&!(*owner)->createTag(u"x",true)&&same(*before,*(*owner)->snapshot()),"Object overflow changed roster/generation");need(bool((*owner)->attach(*one)),"Detached first registration");before=(*owner)->snapshot();need(!(*owner)->attach(*two)&&same(*before,*(*owner)->snapshot()),"Registered quota returned prefix");need(!(*owner)->rename(*one,u"wide")&&same(*before,*(*owner)->snapshot()),"Text quota changed preimage");need(bool((*owner)->remove(*one)),"Bounded removal");*one=i::Token{};auto third=(*owner)->createTag(u"x",true);need(third&&third->id()==3,"Expired detached/removed token was retained or failed creation consumed an ID");before=(*owner)->snapshot();need(!(*owner)->createTag(u"",false)&&same(*before,*(*owner)->snapshot()),"Lifetime creation budget ignored");i::Token empty;need(!(*owner)->remove(empty),"Empty token became authority");
 auto many=i::Owner::create();need(bool(many),"Bounded large metadata owner");for(unsigned index=1;index<=4096;++index){auto value=(*many)->createTag(u"x",true);need(value&&value->id()==static_cast<std::int32_t>(index),"Large roster allocation order changed");}auto held=(*many)->snapshot();need(held&&held->entries.size()==4096&&!(*many)->createTag(u"x",true)&&same(*held,*(*many)->snapshot()),"Maximum roster quota truncated or mutated source");
 i::Limits zero;zero.objects=0;auto none=i::Owner::create(zero);need(none&&!(*none)->createTag(u"",false)&&(*none)->snapshot()->entries.empty(),"Lower zero limit ignored");
}
}
int main(){try{actualInternalConstructorsAndRoster();lifetimeIsolationAndOwningNames();quotasAndCollectedDetachedTokens();}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}std::cout<<"PASS8 actual internal type/tag roster states;detached lifecycle,raw ownership,scope/thread/close and whole-result quotas\n";}
